// smp_helpers.hpp — the small helpers shared by the mtp-smp suite files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
//
// Every suite lives in its own .cpp file and registers itself with a
// mt::static_suite; this header is the only shared code. All functions are
// inline, so including it from every suite is safe.
//
// Shared flags between cores are read and written with __atomic loads and
// stores (a plain load or store plus the barrier the ordering asks for),
// which every SMP core here serialises. Read-modify-write sharing goes
// through the kernel (mutex, critical section) or mtp_board::spinlock: on the
// RP2040/RP2350 the cores do not serialise each other's LDREX/STREX, so a
// std::atomic counter is only exercised in "08 - Atomics".
#pragma once

#include <mtp_board.hpp>

#include <atomic>
#include <cerrno>
#include <cstdint>
#include <cstdio>

namespace mtp_smp
{
  using namespace os::rtos;

  constexpr unsigned ncpu = OS_NCPU;
  constexpr unsigned last = ncpu - 1;

#if defined(__aarch64__) || defined(__x86_64__)
  constexpr std::size_t stack_bytes = 16384;
#else
  constexpr std::size_t stack_bytes = 4096;
#endif

  constexpr clock::duration_t
  ms (unsigned n)
  {
    return static_cast<clock::duration_t> (
        (static_cast<std::uint64_t> (n) * clock_systick::frequency_hz + 999u)
        / 1000u);
  }

  template <typename T>
  T
  load (const volatile T& v)
  {
    return __atomic_load_n (const_cast<const T*> (&v), __ATOMIC_ACQUIRE);
  }

  template <typename T>
  void
  store (volatile T& v, T value)
  {
    __atomic_store_n (const_cast<T*> (&v), value, __ATOMIC_RELEASE);
  }

  inline void*
  as_arg (unsigned value)
  {
    return reinterpret_cast<void*> (static_cast<std::uintptr_t> (value));
  }

  inline unsigned
  from_arg (void* arg)
  {
    return static_cast<unsigned> (reinterpret_cast<std::uintptr_t> (arg));
  }

  // A thread with a stack from the heap, pinned to `core` (or free if < 0).
  inline thread*
  spawn (const char* name, thread::func_t function, void* arg, int core,
         thread::priority_t priority = thread::priority::normal)
  {
    thread::attributes attr;
    attr.th_stack_size_bytes = stack_bytes;
    attr.th_priority = priority;
    if (core >= 0)
      {
        attr.th_cpu_affinity = 1u << static_cast<unsigned> (core);
      }
    return new thread{ name, function, arg, attr };
  }

  inline void
  finish (thread* th)
  {
    (void)th->join ();
    delete th;
  }

  // Spin (not sleep) until `flag` is set or `timeout` ticks pass.
  inline bool
  spin_until (const volatile unsigned& flag, clock::duration_t timeout)
  {
    const auto begin = sysclock.now ();
    while (load (flag) == 0)
      {
        if (sysclock.now () - begin > timeout)
          {
            return false;
          }
        mtp_board::cpu_relax ();
      }
    return true;
  }

  // Sleep in steps until `flag` is set or `timeout` ticks pass.
  inline bool
  wait_until (const volatile unsigned& flag, clock::duration_t timeout)
  {
    const auto begin = sysclock.now ();
    while (load (flag) == 0)
      {
        if (sysclock.now () - begin > timeout)
          {
            return false;
          }
        sysclock.sleep_for (1);
      }
    return true;
  }

  // Spin until `flag` is set, for at most `iterations` looks: for code that
  // holds a lock. On some ports (RP2350) scheduler::critical_section masks
  // this core's interrupts, so the kernel clock stands still inside it and
  // a wait measured with sysclock would never end.
  inline bool
  spin_until_bounded (const volatile unsigned& flag, unsigned iterations)
  {
    for (unsigned i = 0; i < iterations; ++i)
      {
        if (load (flag) != 0)
          {
            return true;
          }
        mtp_board::cpu_relax ();
      }
    return load (flag) != 0;
  }

  // A busy wait that does not need the clock (it may not tick while this
  // core has its interrupts masked).
  inline void
  busy_loop (unsigned iterations)
  {
    for (unsigned i = 0; i < iterations; ++i)
      {
        asm volatile ("" ::: "memory");
      }
  }

  inline const char*
  fmt (const char* format, unsigned value)
  {
    static char text[96];
    std::snprintf (text, sizeof (text), format, value);
    return text;
  }

  // "<what>, through <the board's sync method>"
  inline const char*
  via (const char* format, unsigned value = 0)
  {
    static char text[128];
    char what[64];
    std::snprintf (what, sizeof (what), format, value);
    std::snprintf (text, sizeof (text), "%s, through the %s", what,
                   mtp_board::sync_method ());
    return text;
  }
} // namespace mtp_smp

